16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.AgeBand;
20	import org.springframework.samples.petclinic.util.CityLocality;
21	import org.springframework.samples.petclinic.util.CustomerCode;
22	import org.springframework.samples.petclinic.util.E164PhoneNumber;
23	import org.springframework.samples.petclinic.util.LuhnCheckDigit;
24	import org.springframework.samples.petclinic.util.RegionTimezone;
25	
26	import jakarta.persistence.*;
27	import jakarta.validation.constraints.NotEmpty;
28	import jakarta.validation.constraints.Pattern;
29	
30	import java.time.LocalDate;
31	import java.time.temporal.ChronoUnit;
32	import java.util.*;
33	
34	/**
35	 * Simple JavaBean domain object representing an owner.
36	 *
37	 * @author Ken Krebs
38	 * @author Juergen Hoeller
39	 * @author Sam Brannen
40	 * @author Michael Isvy
41	 */
42	@Entity
43	@Table(name = "owners")
44	public class Owner extends Person {
45	    @Column(name = "address")
46	    @NotEmpty
47	    private String address;
48	
49	    @Column(name = "address_line1")
50	    private String addressLine1;
51	
52	    @Column(name = "address_line2")
53	    private String addressLine2;
54	
55	    @Column(name = "city")
56	    @NotEmpty
57	    private String city;
58	
59	    @Column(name = "telephone")
60	    @NotEmpty
61	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
62	    private String telephone;
63	
64	    @Column(name = "email")
65	    private String email;
66	
67	    @Column(name = "postcode")
68	    private String postcode;
69	
70	    @Column(name = "registration_date")
71	    private LocalDate registrationDate;
72	
73	    @Column(name = "birth_date")
74	    private LocalDate birthDate;
75	
76	    @Column(name = "customer_code")
77	    private String customerCode;
78	
79	    @Column(name = "household_id")
80	    private String householdId;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "household_size")
86	    private Integer householdSize;
87	
88	    @Column(name = "membership_number")
89	    private String membershipNumber;
90	
91	    @Column(name = "bulk_signup_warning", nullable = false)
92	    private boolean bulkSignupWarning;
93	
94	    @Column(name = "possible_duplicate", nullable = false)
95	    private boolean possibleDuplicate;
96	
97	    @Column(name = "possible_duplicate_of")
98	    private Integer possibleDuplicateOf;
99	
100	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
101	    private Set<Pet> pets;
102	
103	    public String getAddress() {
104	        return this.address;
105	    }
106	
107	    public void setAddress(String address) {
108	        this.address = address;
109	    }
110	
111	    /**
112	     * The first line of the owner's structured address, in normalized form, or null when the
113	     * owner was created from the flat {@link #getAddress() address} only. The composed
114	     * {@code address} is derived from this and {@link #getAddressLine2()}.
115	     */
116	    public String getAddressLine1() {
117	        return this.addressLine1;
118	    }
119	
120	    public void setAddressLine1(String addressLine1) {
121	        this.addressLine1 = addressLine1;
122	    }
123	
124	    /**
125	     * The optional second line of the owner's structured address, in normalized form, or null
126	     * when absent or when the owner was created from the flat {@link #getAddress() address}.
127	     */
128	    public String getAddressLine2() {
129	        return this.addressLine2;
130	    }
131	
132	    public void setAddressLine2(String addressLine2) {
133	        this.addressLine2 = addressLine2;
134	    }
135	
136	    public String getCity() {
137	        return this.city;
138	    }
139	
140	    public void setCity(String city) {
141	        this.city = city;
142	    }
143	
144	    public String getTelephone() {
145	        return this.telephone;
146	    }
147	
148	    public void setTelephone(String telephone) {
149	        this.telephone = telephone;
150	    }
151	
152	    /**
153	     * The stored E.164 telephone formatted for humans: the country code, a space, then the
154	     * national digits grouped in threes (e.g. {@code "+61 412 345 678"}), while
155	     * {@link #getTelephone()} keeps the raw E.164 form. Derived from stored state, never
156	     * persisted.
157	     */
158	    public String getTelephoneDisplay() {
159	        return E164PhoneNumber.toDisplay(this.telephone);
160	    }
161	
162	    public String getEmail() {
163	        return this.email;
164	    }
165	
166	    public void setEmail(String email) {
167	        this.email = email;
168	    }
169	
170	    /**
171	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
172	     * against the city's region and then stored verbatim. Optional, so may be null.
173	     */
174	    public String getPostcode() {
175	        return this.postcode;
176	    }
177	
178	    public void setPostcode(String postcode) {
179	        this.postcode = postcode;
180	    }
181	
182	    public LocalDate getRegistrationDate() {
183	        return this.registrationDate;
184	    }
185	
186	    public void setRegistrationDate(LocalDate registrationDate) {
187	        this.registrationDate = registrationDate;
188	    }
189	
190	    /**
191	     * The owner's date of birth. Optional, so may be null.
192	     */
193	    public LocalDate getBirthDate() {
194	        return this.birthDate;
195	    }
196	
197	    public void setBirthDate(LocalDate birthDate) {
198	        this.birthDate = birthDate;
199	    }
200	
201	    /**
202	     * The owner's age band as at registration: {@code "MINOR"} for under 18,
203	     * {@code "ADULT"} for 18 to 64, or {@code "SENIOR"} for 65 and over, measured from the
204	     * birth date against the registration date. Null when no birth date is recorded.
205	     * Derived from stored state, never persisted.
206	     */
207	    public String getAgeBand() {
208	        if (this.birthDate == null || this.registrationDate == null) {
209	            return null;
210	        }
211	        return AgeBand.of(this.birthDate, this.registrationDate);
212	    }
213	
214	    public String getCustomerCode() {
215	        return this.customerCode;
216	    }
217	
218	    public void setCustomerCode(String customerCode) {
219	        this.customerCode = customerCode;
220	    }
221	
222	    /**
223	     * The stable identifier of the household this owner belongs to: the first twelve hex
224	     * characters of the SHA-256 of the normalized last name and postcode, so every owner
225	     * sharing a last name and postcode resolves to the same value. Null when the owner has
226	     * no postcode. Assigned at creation.
227	     */
228	    public String getHouseholdId() {
229	        return this.householdId;
230	    }
231	
232	    public void setHouseholdId(String householdId) {
233	        this.householdId = householdId;
234	    }
235	
236	    public Integer getNamesakeCount() {
237	        return this.namesakeCount;
238	    }
239	
240	    public void setNamesakeCount(Integer namesakeCount) {
241	        this.namesakeCount = namesakeCount;
242	    }
243	
244	    public Integer getHouseholdSize() {
245	        return this.householdSize;
246	    }
247	
248	    public void setHouseholdSize(Integer householdSize) {
249	        this.householdSize = householdSize;
250	    }
251	
252	    public String getMembershipNumber() {
253	        return this.membershipNumber;
254	    }
255	
256	    public void setMembershipNumber(String membershipNumber) {
257	        this.membershipNumber = membershipNumber;
258	    }
259	
260	    /**
261	     * Whether this owner was created as part of a bulk signup: {@code true} when more
262	     * than 80 owners had already been registered on this owner's registration date at
263	     * the moment it was created, {@code false} otherwise. Captured at creation.
264	     */
265	    public boolean isBulkSignupWarning() {
266	        return this.bulkSignupWarning;
267	    }
268	
269	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
270	        this.bulkSignupWarning = bulkSignupWarning;
271	    }
272	
273	    /**
274	     * Whether this owner resembles an existing one: {@code true} when, at creation, it
275	     * shared an existing owner's household (same last name and postcode, hence the same
276	     * {@link #getHouseholdId() household id}) while having a different telephone and was not
277	     * a declared household member, {@code false} otherwise. A declared member (created with
278	     * {@code sharesHousehold}) is a genuine member, not a suspected duplicate. When true,
279	     * {@link #getPossibleDuplicateOf()} holds that owner's id. Captured at creation.
280	     */
281	    public boolean isPossibleDuplicate() {
282	        return this.possibleDuplicate;
283	    }
284	
285	    public void setPossibleDuplicate(boolean possibleDuplicate) {
286	        this.possibleDuplicate = possibleDuplicate;
287	    }
288	
289	    /**
290	     * The id of the existing owner this owner possibly duplicates (same household — last
291	     * name and postcode — different telephone), or null when it is not a possible
292	     * duplicate. Captured at creation.
293	     */
294	    public Integer getPossibleDuplicateOf() {
295	        return this.possibleDuplicateOf;
296	    }
297	
298	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
299	        this.possibleDuplicateOf = possibleDuplicateOf;
300	    }
301	
302	    /**
303	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
304	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
305	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
306	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
307	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
308	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
309	     * region is derived directly from the stored postcode and city. Derived from stored
310	     * state, never persisted.
311	     */
312	    public String getLocality() {
313	        String region = CustomerCode.regionOf(this.customerCode);
314	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
315	    }
316	
317	    /**
318	     * The owner's timezone: the IANA name for this owner's {@link #getLocality() locality}
319	     * via the fixed region-to-timezone table (NSW->Australia/Sydney,
320	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region
321	     * has no known timezone. Derived from stored state, never persisted.
322	     */
323	    public String getTimezone() {
324	        return RegionTimezone.forRegion(getLocality());
325	    }
326	
327	    /**
328	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
329	     * has an email address, gains 1 when this owner had no namesakes at creation
330	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
331	     * members, and gains 3 when this owner's tenure exceeds 365 days. A newly created owner
332	     * has zero tenure, so it never earns those points at creation. Derived from stored
333	     * state, never persisted.
334	     */
335	    public int getMembershipPoints() {
336	        int points = 0;
337	        if (hasEmail()) {
338	            points += 2;
339	        }
340	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
341	            points += 1;
342	        }
343	        if (this.householdSize != null && this.householdSize >= 3) {
344	            points += 2;
345	        }
346	        if (getTenureDays() > 365) {
347	            points += 3;
348	        }
349	        return points;
350	    }
351	
352	    /**
353	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
354	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Derived from
355	     * stored state, never persisted.
356	     */
357	    public int getMembershipLevel() {
358	        int points = getMembershipPoints();
359	        if (points <= 1) {
360	            return 1;
361	        }
362	        if (points <= 3) {
363	            return 2;
364	        }
365	        if (points <= 5) {
366	            return 3;
367	        }
368	        return 4;
369	    }
370	
371	    /**
372	     * The owner's tenure in whole days: the number of days from the {@code registrationDate}
373	     * to the current server date, or 0 when no registration date is recorded. Never negative
374	     * in practice, since a future registration date is rejected at creation.
375	     */
376	    private long getTenureDays() {
377	        if (this.registrationDate == null) {
378	            return 0;
379	        }
380	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
381	    }
382	
383	    /**
384	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
385	     * the {@code customerCode}. Derived from stored state, never persisted.
386	     */
387	    public int getCheckDigit() {
388	        return LuhnCheckDigit.of(this.customerCode);
389	    }
390	
391	    /**
392	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
393	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
394	     */
395	    public String getContactPreference() {
396	        return hasEmail() ? "EMAIL" : "PHONE";
397	    }
398	
399	    /**
400	     * The owner's identity key: a composite fingerprint formed as the normalized telephone,
401	     * the email (or empty when absent) and the household id (or empty when none), joined by
402	     * {@code '|'}. Derived from stored state, never persisted.
403	     */
404	    public String getIdentityKey() {
405	        String emailPart = hasEmail() ? this.email : "";
406	        String householdPart = this.householdId == null ? "" : this.householdId;
407	        return this.telephone + "|" + emailPart + "|" + householdPart;
408	    }
409	
410	    private boolean hasEmail() {
411	        return this.email != null && !this.email.isEmpty();
412	    }
413	
414	    protected Set<Pet> getPetsInternal() {
415	        if (this.pets == null) {
416	            this.pets = new HashSet<>();
417	        }
418	        return this.pets;
419	    }
420	
421	    protected void setPetsInternal(Set<Pet> pets) {
422	        this.pets = pets;
423	    }
424	
425	    public List<Pet> getPets() {
426	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
427	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
428	        return Collections.unmodifiableList(sortedPets);
429	    }
430	
431	    public void setPets(List<Pet> pets) {
432	        this.pets = new HashSet<>(pets);
433	    }
434	
435	    public void addPet(Pet pet) {
436	        getPetsInternal().add(pet);
437	        pet.setOwner(this);
438	    }
439	
440	    /**
441	     * Return the Pet with the given name, or null if none found for this Owner.
442	     *
443	     * @param name to test
444	     * @return true if pet name is already in use
445	     */
446	    public Pet getPet(String name) {
447	        return getPet(name, false);
448	    }
449	
450	    /**
451	     * Return the Pet with the given name, or null if none found for this Owner.
452	     *
453	     * @param name to test
454	     * @return true if pet name is already in use
455	     */
456	    public Pet getPet(String name, boolean ignoreNew) {
457	        name = name.toLowerCase();
458	        for (Pet pet : getPetsInternal()) {
459	            if (!ignoreNew || !pet.isNew()) {
460	                String compName = pet.getName();
461	                compName = compName.toLowerCase();
462	                if (compName.equals(name)) {
463	                    return pet;
464	                }
465	            }
466	        }
467	        return null;
468	    }
469	
470	    public Pet getPet(Integer petId) {
471	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
472	    }
473	
474	    @Override
475	    public String toString() {
476	        return new ToStringCreator(this)
477	
478	            .append("id", this.getId())
479	            .append("new", this.isNew())
480	            .append("lastName", this.getLastName())
481	            .append("firstName", this.getFirstName())
482	            .append("address", this.address)
483	            .append("city", this.city)
484	            .append("telephone", this.telephone)
485	            .toString();
486	    }
487	}
