3	import java.util.List;
4	
5	/**
6	 * Thrown when a create-owner request omits or blanks a required field.
7	 * Carries the names of the offending fields; handled by
8	 * {@link MissingOwnerFieldsExceptionHandler}, which responds 400 with an {@code errors} array.
9	 */
10	public class MissingOwnerFieldsException extends Exception {
11	
12	    private final List<String> fields;
13	
14	    public MissingOwnerFieldsException(List<String> fields) {
15	        super("Missing or blank required owner fields: " + String.join(", ", fields));
16	        this.fields = List.copyOf(fields);
17	    }
18	
19	    public List<String> getFields() {
20	        return this.fields;
21	    }
22	}
