9	public class MissingOwnerFieldsExceptionHandler {
10	
11	    public void handle(@Parameter MissingOwnerFieldsException ex,
12	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
13	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
14	                "The request is missing required owner fields");
15	        detail.setProperty("errors", ex.getFields());
16	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
17	    }
