1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.util.AddressNormalizer;
6	import org.springframework.web.bind.annotation.RequestBody;
7	
8	/**
9	 * First step of the create-owner pipeline: reads the request body once, normalizes whichever
10	 * address fields it supplies to canonical form (see {@link AddressNormalizer}) and republishes
11	 * the body so downstream steps consume it as {@code @Val}.
12	 *
13	 * <p>The structured fields are preferred when present: a non-blank {@code addressLine1} (with an
14	 * optional {@code addressLine2}) is normalized in place, and the flat {@code address} is set to
15	 * their composed form. Otherwise the flat {@code address} is normalized as before, keeping the
16	 * contract backward-compatible. Either way the flat {@code address} carries the effective
17	 * address, so everything downstream — {@link ValidateOwnerFields}, {@link BuildOwner} (hence the
18	 * persisted and returned value) and household comparison (see {@link Households}) — works from the
19	 * normalized, preferred form.
20	 */
21	public class NormalizeOwnerAddress {
22	
23	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> normalized) {
24	        String line1 = request.getAddressLine1();
25	        if (line1 != null && !line1.isBlank()) {
26	            String normalizedLine2 = AddressNormalizer.normalize(request.getAddressLine2());
27	            request.setAddressLine1(AddressNormalizer.normalize(line1));
28	            request.setAddressLine2(normalizedLine2.isEmpty() ? null : normalizedLine2);
29	            request.setAddress(AddressNormalizer.compose(line1, normalizedLine2));
30	        }
31	        else {
32	            request.setAddress(AddressNormalizer.normalize(request.getAddress()));
33	        }
34	        normalized.set(request);
35	    }
36	}
